operation.document:
query ListDocuments($filter: DocumentFilter, $first: Int) {
  documents(filter: $filter, first: $first) {
    nodes {
      id
      title
      slugId
      url
      updatedAt
      project {
        name
        slugId
      }
      issue {
        identifier
        title
      }
      initiative {
        name
        slugId
      }
      team {
        name
        key
      }
      cycle {
        name
        number
        team {
          key
        }
      }
      release {
        name
        version
      }
      creator {
        name
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}
